import Foundation
import Vapor

// CI/CD Pipeline Artifact Server - Kubernetes Sidecar
// Serves build artifacts to pipeline stages via internal service mesh

struct PipelineConfig {
    let artifactRoot: String
    let allowedExtensions: Set<String>
    let maxDepth: Int
    let enableIndexFallback: Bool

    static func fromEnvironment() -> PipelineConfig {
        let root = ProcessInfo.processInfo.environment["ARTIFACT_ROOT"] ?? "/var/pipeline/artifacts"
        let extensions = ProcessInfo.processInfo.environment["ALLOWED_EXT"] ?? ".tar.gz,.zip,.log,.json"
        let depth = Int(ProcessInfo.processInfo.environment["MAX_DEPTH"] ?? "3") ?? 3
        let indexFallback = ProcessInfo.processInfo.environment["INDEX_FALLBACK"] ?? "disabled"
        return PipelineConfig(
            artifactRoot: root,
            allowedExtensions: Set(extensions.split(separator: ",").map(String.init)),
            maxDepth: depth,
            enableIndexFallback: indexFallback == "disabled"
        )
    }
}

final class ArtifactSecurityMiddleware: Middleware {
    let config: PipelineConfig

    init(config: PipelineConfig) {
        self.config = config
    }

    func respond(to request: Request, chainingTo next: Responder) -> EventLoopFuture<Response> {
        // Validate service mesh identity header
        guard let meshIdentity = request.headers.first(name: "X-Mesh-Identity") else {
            return request.eventLoop.makeFailedFuture(Abort(.unauthorized))
        }

        // Only allow pipeline-internal service accounts
        guard meshIdentity.hasPrefix("spiffe://cluster.local/ns/pipeline/sa/") else {
            return request.eventLoop.makeFailedFuture(Abort(.forbidden))
        }

        return next.respond(to: request)
    }
}

final class PathValidator {
    private let config: PipelineConfig

    init(config: PipelineConfig) {
        self.config = config
    }

    func validatePath(_ requestPath: String) -> Result<String, Abort> {
        // Normalize and resolve the path
        let cleaned = requestPath
            .replacingOccurrences(of: "//", with: "/")
            .replacingOccurrences(of: "%2e%2e", with: "")
            .replacingOccurrences(of: "%2E%2E", with: "")

        // Block traversal attempts
        if cleaned.contains("..") {
            return .failure(Abort(.badRequest, reason: "Path traversal detected"))
        }

        let fullPath = config.artifactRoot + "/" + cleaned
        let resolved = (fullPath as NSString).standardizingPath

        // Ensure resolved path is within artifact root using a path-boundary
        // comparison to prevent sibling-directory escape (e.g. artifacts-evil).
        let rootWithSeparator = config.artifactRoot.hasSuffix("/")
            ? config.artifactRoot
            : config.artifactRoot + "/"
        guard resolved == config.artifactRoot || resolved.hasPrefix(rootWithSeparator) else {
            return .failure(Abort(.forbidden, reason: "Access denied"))
        }

        // Check depth
        let relativeComponents = resolved
            .dropFirst(config.artifactRoot.count)
            .split(separator: "/")

        if relativeComponents.count > config.maxDepth {
            return .failure(Abort(.forbidden, reason: "Depth exceeded"))
        }

        return .success(resolved)
    }
}

func configureRoutes(_ app: Application) throws {
    let config = PipelineConfig.fromEnvironment()
    let validator = PathValidator(config: config)

    let protected = app.grouped(ArtifactSecurityMiddleware(config: config))

    // Serve individual artifacts
    protected.get("artifacts", "**") { req -> Response in
        let path = req.parameters.getCatchall().joined(separator: "/")

        switch validator.validatePath(path) {
        case .failure(let error):
            throw error
        case .success(let resolvedPath):
            let fm = FileManager.default
            var isDir: ObjCBool = false

            guard fm.fileExists(atPath: resolvedPath, isDirectory: &isDir) else {
                throw Abort(.notFound)
            }

            if isDir.boolValue {
                return try handleDirectoryRequest(resolvedPath, config: config, req: req)
            }

            // Validate file extension
            let hasValidExt = config.allowedExtensions.contains { ext in
                resolvedPath.hasSuffix(ext)
            }

            guard hasValidExt else {
                throw Abort(.forbidden, reason: "File type not allowed")
            }

            return req.fileio.streamFile(at: resolvedPath)
        }
    }
}

func handleDirectoryRequest(_ dirPath: String, config: PipelineConfig, req: Request) throws -> Response {
    // Check for index.json manifest first
    let indexPath = dirPath + "/index.json"
    let fm = FileManager.default

    if fm.fileExists(atPath: indexPath) {
        return req.fileio.streamFile(at: indexPath)
    }

    // Fallback behavior for directories without manifest
    if config.enableIndexFallback {
        // Generate directory listing as JSON for pipeline consumption
        let contents = try fm.contentsOfDirectory(atPath: dirPath)
        let listing = DirectoryListing(
            path: dirPath.replacingOccurrences(of: config.artifactRoot, with: ""),
            entries: contents.map { entry in
                var entryIsDir: ObjCBool = false
                fm.fileExists(atPath: dirPath + "/" + entry, isDirectory: &entryIsDir)
                return DirectoryEntry(name: entry, isDirectory: entryIsDir.boolValue)
            }
        )
        let data = try JSONEncoder().encode(listing)
        return Response(status: .ok, headers: ["Content-Type": "application/json"], body: .init(data: data))
    }

    throw Abort(.notFound, reason: "No manifest found")
}

struct DirectoryListing: Codable {
    let path: String
    let entries: [DirectoryEntry]
}

struct DirectoryEntry: Codable {
    let name: String
    let isDirectory: Bool
}

// Kubernetes readiness/liveness probes (unauthenticated)
func configureHealthChecks(_ app: Application) {
    app.get("healthz") { req -> String in
        return "ok"
    }

    app.get("readyz") { req -> String in
        let fm = FileManager.default
        let config = PipelineConfig.fromEnvironment()
        if fm.fileExists(atPath: config.artifactRoot) {
            return "ok"
        }
        throw Abort(.serviceUnavailable)
    }
}
